'use strict';
// Credentials stay in memory unless the user opts into tab-scoped session storage.
(()=>{
const providers={rd:{name:'Real-Debrid',base:'https://api.real-debrid.com/rest/1.0/',auth:'https://api.real-debrid.com/oauth/v2/'},ad:{name:'AllDebrid',base:'https://api.alldebrid.com/v4/'}};
const sessions={};let afterADConnect=null;let screen=0,active=false;
for(const p of ['rd','ad']){try{const saved=JSON.parse(sessionStorage.getItem('mono-debrid-'+p)||'null');if(saved&&typeof saved.token==='string'&&saved.token.length<=4096&&Number.isFinite(saved.expires)&&saved.expires>Date.now())sessions[p]=saved}catch{}}
function changed(){try{document.dispatchEvent(new Event('oktawka:debrid'))}catch{}}
function clearSession(p){delete sessions[p];changed();try{sessionStorage.removeItem('mono-debrid-'+p)}catch{}}
function saveSession(p,token,expires){sessions[p]={token,expires};changed();try{if($('#debrid-remember')?.checked)sessionStorage.setItem('mono-debrid-'+p,JSON.stringify(sessions[p]));else sessionStorage.removeItem('mono-debrid-'+p)}catch{}}
function finishConnection(p){if(p==='ad'&&afterADConnect){const resume=afterADConnect;afterADConnect=null;cancel();active=false;resume();return true}return false}
function connectionError(message){const error=new Error(message);error.code='DEBRID_AUTH_REQUIRED';return error}
const requests=new Set();const directSource=$('#connect').onclick;
function safeLink(value){try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password?u.href:''}catch{return ''}}
function report(message){const el=$('#debrid-status');if(el)el.textContent=message}
function authToken(p){const s=sessions[p];if(!s)throw connectionError('Connect '+providers[p].name+' in this tab to play this source.');if(s.expires<=Date.now()){clearSession(p);throw connectionError('Your '+providers[p].name+' connection expired. Reconnect to continue playback.')}return s.token}
function apiError(p,j,status){const code=p==='ad'?j?.error?.code:j?.error;if(status===401||['AUTH_BAD_APIKEY','AUTH_MISSING_APIKEY','bad_token'].includes(code)){clearSession(p);return connectionError('Your '+providers[p].name+' key is no longer valid. Reconnect to continue playback.')}const known={AUTH_BAD_APIKEY:'Connection expired or invalid. Reconnect your account.',AUTH_BLOCKED:'Your account needs verification on the provider website.',AUTH_USER_BANNED:'The provider has blocked this account.',AUTH_MISSING_APIKEY:'Connect your account first.',MUST_BE_PREMIUM:'This link requires a premium provider account.',LINK_HOST_NOT_SUPPORTED:'This file host is not supported by your provider.',LINK_DOWN:'This file is no longer available.',LINK_PASS_PROTECTED:'This link needs a password. Use the provider website to unlock it.',LINK_HOST_UNAVAILABLE:'The file host is temporarily unavailable.',LINK_HOST_LIMIT_REACHED:'Your provider limit for this file host has been reached.',NO_SERVER:'The provider does not allow this connection. Check its VPN/IP settings.',bad_token:'Connection expired or invalid. Reconnect your account.',permission_denied:'The provider denied access. Check your account and subscription.',hoster_not_free:'A premium account is required for this host.',hoster_unsupported:'This file host is not supported.',hoster_unavailable:'The file host is temporarily unavailable.',hoster_limit_reached:'The host download limit has been reached.',ip_not_allowed:'The provider does not allow this IP address.',traffic_exhausted:'Your provider traffic allowance has been exhausted.'};return new Error(known[code]||(status===429?'Provider rate limit reached. Wait before trying again.':status===401?'Connection expired or invalid. Reconnect your account.':status===403?'Provider access denied. Check account authorization, subscription, or IP restrictions.':'The provider could not complete the request. Check the link or try again later.'))}
async function call(p,path,{params,post,token,oauth=false}={}){const cfg=providers[p];const url=new URL(path,oauth?cfg.auth:cfg.base);if(params)url.search=new URLSearchParams(params);const controller=new AbortController();requests.add(controller);const timeout=setTimeout(()=>controller.abort(),25000);try{const response=await fetch(url,{method:post?'POST':'GET',headers:token?{Authorization:'Bearer '+token}:{},body:post?new URLSearchParams(post):undefined,signal:controller.signal,credentials:'omit',cache:'no-store',referrerPolicy:'no-referrer',redirect:'error'});const json=await response.json();if(!response.ok||(p==='ad'&&json.status!=='success')||(p==='rd'&&json.error))throw apiError(p,json,response.status);return p==='ad'?json.data:json}catch(e){if(e instanceof TypeError||e.name==='SyntaxError')throw new Error('The provider could not be reached. It may be unavailable or blocking browser requests.');if(e.name==='AbortError')throw new Error('Request cancelled or timed out. Please try again.');throw e}finally{clearTimeout(timeout);requests.delete(controller)}}
function cancel(){screen++;for(const r of requests)r.abort();requests.clear()}
function frame(html){cancel();active=true;modal(`<div class="eyebrow">YOUR FILES, MORE WAYS TO LISTEN</div><h2>Music sources.</h2>${html}<p id="debrid-status" class="note" role="status" aria-live="polite"></p><p class="note debrid-privacy">Keys stay in memory by default. If you choose Keep connected in this tab, the key is saved in tab-scoped browser storage until this tab closes. Requests go directly to your provider; keys are not stored on Oktawka servers.</p>`)}
async function action(button,fn){if(button.disabled)return;const version=screen;button.disabled=true;try{await fn(version)}catch(e){if(version===screen)report(e.message)}finally{if(version===screen)button.disabled=false}}
function choose(){afterADConnect=null;frame(`<p>Add audio through your own Real-Debrid or AllDebrid account, or use a direct audio URL.</p><div class="source-options">${Object.entries(providers).map(([p,c])=>`<button class="source-option" data-provider="${p}"><span class="source-icon">${p==='rd'?'RD':'AD'}</span><span><b>${c.name}</b><small>${sessions[p]&&sessions[p].expires>Date.now()?'Connected in this tab':'Connect your account'}</small></span><span>↗</span></button>`).join('')}<button class="source-option" id="direct-audio"><span class="source-icon">↗</span><span><b>Direct audio URL</b><small>Add an HTTPS stream</small></span><span>↗</span></button></div><p class="note">Use supported links for files you have access to. Account and host limits apply. Debrid does not search the album catalog.</p>`);document.querySelectorAll('[data-provider]').forEach(b=>b.onclick=()=>provider(b.dataset.provider));$('#direct-audio').onclick=()=>{cancel();active=false;directSource()}}
function cloudPanel(){return `<section class="cloud-library"><h3>Search cloud music</h3><p class="note">Find external lossless releases and play through your connected AllDebrid account. You do not need to upload or host music.</p><button class="primary" id="search-ad-music">Search artists & albums ↗</button></section>`}
function flattenCloud(nodes){const found=[],stack=Array.isArray(nodes)?nodes.map(n=>({node:n,path:''})).reverse():[];let visited=0;while(stack.length&&visited++<20000&&found.length<1000){const {node,path}=stack.pop();if(!node||typeof node!=='object')continue;const name=typeof node.n==='string'?node.n:'';if(Array.isArray(node.e)){for(let i=node.e.length-1;i>=0;i--)stack.push({node:node.e[i],path:path+name+'/'});}else{const row={filename:name,link:node.l,path};if(audioFile(row,'ad'))found.push(row)}}return found}

function provider(p){const c=providers[p],connected=sessions[p]&&sessions[p].expires>Date.now();frame(`<button class="source-back" id="source-back">← All sources</button><div class="provider-title"><span class="source-icon">${p==='rd'?'RD':'AD'}</span><h3>${c.name}</h3><span class="connection-state">${connected?'Connected':'Not connected'}</span></div>${connected?`${p==='ad'?cloudPanel()+'<details class="manual-link"><summary>Or paste a file link manually</summary>':'<p>Paste a supported hoster link to an individual audio file.</p>'}<form id="debrid-link-form"><label for="debrid-link">File link</label><input id="debrid-link" type="url" required placeholder="https://file-host.example/song.flac" autocomplete="off"><button class="primary" type="submit" id="grab-link">Grab audio link ↗</button></form>${p==='ad'?'</details>':''}<div id="debrid-result"></div><button class="disconnect" id="debrid-disconnect">Disconnect ${c.name}</button>`:`<p>Paste your ${c.name} API key to connect this tab.</p><form id="debrid-key-form"><label for="debrid-api-key">${p==='rd'?'API token':'API key'}</label><input id="debrid-api-key" type="password" required maxlength="4096" placeholder="Paste your API key" autocomplete="off" autocapitalize="none" spellcheck="false"><label class="remember-connection"><input id="debrid-remember" type="checkbox"> Keep connected in this tab across refreshes</label><button class="primary" id="debrid-key-connect" type="submit">Connect with API key ↗</button></form><a class="key-dashboard" href="${p==='rd'?'https://real-debrid.com/apitoken':'https://alldebrid.com/apikeys/'}" target="_blank" rel="noopener noreferrer">Get your key on ${c.name} ↗</a><div class="auth-alternative"><p class="note">Or authorize without pasting a key:</p><button class="source-back" id="debrid-authorize">Use ${p==='rd'?'device authorization':'PIN authorization'} ↗</button><div id="debrid-auth"></div></div>`}<p class="note">Supports individual FLAC, WAV, MP3, M4A, AAC, OGG, OPUS, and AIFF files. Archives, new magnet uploads, and automatic album matching are not supported. AllDebrid resolves releases selected in Cloud music. Audio quality and codec support depend on the file and browser.</p>`);$('#source-back').onclick=choose;if(connected){if(p==='ad')$('#search-ad-music').onclick=()=>{cancel();active=false;window.monoOpenAddons()};$('#debrid-disconnect').onclick=()=>{clearSession(p);afterADConnect=null;provider(p);report('Disconnected. You can revoke app access on the provider website.')};$('#debrid-link-form').onsubmit=e=>{e.preventDefault();action($('#grab-link'),async version=>{const link=safeLink($('#debrid-link').value.trim());if(!link)throw new Error('Enter a valid HTTPS file link.');$('#debrid-result').innerHTML='';report('Resolving your link…');const token=authToken(p);const data=await call(p,p==='rd'?'unrestrict/link':'link/unlock',{post:{link},token});if(version!==screen)return;showResult(p,data,version)})}}else {$('#debrid-key-form').onsubmit=e=>{e.preventDefault();return action($('#debrid-key-connect'),async version=>{const input=$('#debrid-api-key');const token=input.value.trim();input.value='';if(!token||token.length>4096||/\s/.test(token))throw new Error('Paste a valid API key without spaces.');report('Checking your API key…');const result=await call(p,'user',{token});if(version!==screen)return;const user=p==='ad'?result?.user:result;if(!user||typeof user.username!=='string')throw new Error('The provider could not verify this API key.');saveSession(p,token,Number.MAX_SAFE_INTEGER);if(finishConnection(p))return;provider(p);report(p==='ad'?'API key verified. Use Search artists & albums to find external music.':'API key verified. Connected for this tab. Paste a file link to get started.');})};$('#debrid-authorize').onclick=()=>action($('#debrid-authorize'),version=>authorize(p,version))}}
async function authorize(p,version){report('Requesting an authorization code…');const client='X245A4XAIBGVM';const data=p==='rd'?await call(p,'device/code',{oauth:true,params:{client_id:client,new_credentials:'yes'}}):await call(p,'https://api.alldebrid.com/v4.1/pin/get');if(version!==screen)return;const code=p==='rd'?data.user_code:data.pin;const rawURL=p==='rd'?data.verification_url:data.user_url;const href=safeLink(rawURL);if(!href||new URL(href).hostname!==(p==='rd'?'real-debrid.com':'alldebrid.com')||!code)throw new Error('The provider returned invalid authorization details.');const expires=Date.now()+Math.max(0,Number(data.expires_in)||0)*1000;let nextCheck=Date.now()+Math.max(5,Number(data.interval)||5)*1000;$('#debrid-auth').innerHTML=`<div class="auth-code"><small>YOUR AUTHORIZATION CODE</small><strong>${escapeHTML(code)}</strong><a href="${escapeHTML(href)}" target="_blank" rel="noopener noreferrer">Authorize on ${providers[p].name} ↗</a><button class="primary" id="debrid-check">I authorized it — finish connecting</button></div>`;report('Open the provider page, enter the code if needed, and approve access.');$('#debrid-check').onclick=()=>action($('#debrid-check'),async currentScreen=>{if(Date.now()>=expires)throw new Error('The code expired. Go back and request a new code.');if(Date.now()<nextCheck)throw new Error('Wait a few seconds before checking authorization again.');nextCheck=Date.now()+Math.max(5,Number(data.interval)||5)*1000;let token,validity=3600;if(p==='rd'){let credentials;try{credentials=await call(p,'device/credentials',{oauth:true,params:{client_id:client,code:data.device_code}})}catch(e){if(e.message.includes('cancelled')||e.message.includes('reached'))throw e;throw new Error('Authorization is not complete. Approve access on Real-Debrid, then try again.')}if(currentScreen!==screen)return;if(!credentials.client_id||!credentials.client_secret)throw new Error('Authorization is not complete yet.');const result=await call(p,'token',{oauth:true,post:{client_id:credentials.client_id,client_secret:credentials.client_secret,code:data.device_code,grant_type:'http://oauth.net/grant_type/device/1.0'}});token=result.access_token;validity=Number(result.expires_in)||3600}else{const result=await call(p,'pin/check',{post:{pin:data.pin,check:data.check}});if(!result.activated||!result.apikey)throw new Error('Authorization is not complete. Approve access on AllDebrid, then try again.');token=result.apikey;validity=86400}if(currentScreen!==screen)return;if(typeof token!=='string'||!token)throw new Error('No account token was returned. Please reconnect.');saveSession(p,token,Date.now()+validity*1000);if(finishConnection(p))return;provider(p);report(p==='ad'?'Account connected. Use Search artists & albums to find external music.':'Account connected for this tab. Paste a file link to get started.')})}
function audioFile(item,p){const filename=typeof item?.filename==='string'?item.filename:'';const url=safeLink(p==='rd'?item.download:item.link);const match=filename.match(/\.(flac|wav|mp3|m4a|aac|ogg|opus|aiff|aif)$/i);if(!url||!match)return null;return {filename,url,ext:match[1].toUpperCase()}}
function showResult(p,data,version){const target=$('#debrid-result');const rows=Array.isArray(data)?data:[data];if(p==='ad'&&data?.delayed&&!data?.link){let nextCheck=Date.now()+5000;target.innerHTML='<div class="debrid-result"><b>Your provider is preparing the file.</b><p class="note">Check again after a few seconds. No background polling runs.</p><button class="primary" id="check-delayed">Check file status</button></div>';report('File preparation is pending.');$('#check-delayed').onclick=()=>action($('#check-delayed'),async()=>{if(Date.now()<nextCheck)throw new Error('Wait at least five seconds before checking again.');nextCheck=Date.now()+5000;const result=await call(p,'link/delayed',{post:{id:String(data.delayed)},token:authToken(p)});if(version!==screen)return;if(result.status===3)throw new Error('The provider could not prepare this file. Try another link.');if(result.status===2&&result.link)showResult(p,{...data,link:result.link,delayed:null},version);else report('The provider is still preparing the file. Check again shortly.')});return}const files=rows.map(item=>audioFile(item,p)).filter(Boolean);if(!files.length){target.innerHTML='<p class="note">No supported audio file was returned. Use an individual audio link; archives, video streams, and folders cannot be added.</p>';report('No playable audio link found.');return}target.innerHTML=files.map((file,i)=>`<div class="debrid-result"><b>${escapeHTML(file.filename)}</b><p class="note">${file.ext} · Original file, quality unverified</p><button class="primary" data-add-debrid="${i}">＋ Add to music library</button></div>`).join('');report(`${files.length} audio file${files.length===1?'':'s'} ready to add.`);target.querySelectorAll('[data-add-debrid]').forEach(b=>b.onclick=()=>{const file=files[Number(b.dataset.addDebrid)];if(tracks.some(t=>t.url===file.url)){toast('This file is already in your music library.');return}tracks.push({title:file.filename.replace(/\.[^.]+$/,''),artist:providers[p].name+' · connected file',url:file.url,lossless:false,format:file.ext+' · unverified'});b.disabled=true;b.textContent='✓ Added to library';render();toast('Audio added. Select the track in your library to listen.')})}
window.monoAllDebridTorrent=async ({hash,id})=>{const token=authToken('ad');let magnet;if(id){const result=await call('ad','https://api.alldebrid.com/v4.1/magnet/status',{post:{id:String(id)},token});magnet=Array.isArray(result.magnets)?result.magnets.find(m=>String(m.id)===String(id)):result.magnets;if(!magnet||Number(magnet.statusCode)>4)throw new Error('AllDebrid could not prepare this source.');if(Number(magnet.statusCode)!==4)return {pending:true,id};}else{if(!/^[a-f0-9]{40}$/i.test(hash||''))throw new Error('The addon returned an unsupported torrent hash.');const result=await call('ad','magnet/upload',{post:{'magnets[]':hash},token});magnet=result.magnets?.[0];if(!magnet||magnet.error||!/^\d+$/.test(String(magnet.id)))throw new Error('AllDebrid could not add this source.');id=magnet.id;if(!magnet.ready)return {pending:true,id};}const result=await call('ad','magnet/files',{post:{'id[]':String(id)},token});const files=result.magnets?.find(m=>String(m.id)===String(id));if(!files||files.error)throw new Error('AllDebrid could not list this source’s audio files.');return {pending:false,id,files:flattenCloud(files.files)}};
window.monoResolveAllDebrid=async link=>{const url=safeLink(link);if(!url)throw new Error('The addon did not supply a supported HTTPS source.');return call('ad','link/unlock',{post:{link:url},token:authToken('ad')})};
window.monoHasDebrid=()=>Object.values(sessions).some(x=>x&&x.expires>Date.now());
window.monoHasAllDebrid=()=>Boolean(sessions.ad&&sessions.ad.expires>Date.now());
window.monoConnectAllDebrid=resume=>{afterADConnect=typeof resume==='function'?resume:null;provider('ad')};
$('#connect').onclick=choose;$('#debrid-source').onclick=choose;$('#dialog').addEventListener('close',()=>{if(active){cancel();active=false;afterADConnect=null}});
})();
